export function artwork(kind,id='art'){
 const safeId=String(id).replace(/[^a-zA-Z0-9-]/g,'');
 const scene=(scenes[kind]||scenes.custom).replaceAll('url(#metal)',`url(#metal-${safeId})`).replaceAll('url(#sphere)',`url(#sphere-${safeId})`);
 return `<svg viewBox="0 0 400 220" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="metal-${safeId}"><stop stop-color="#68798f"/><stop offset=".4" stop-color="#e3e9f1"/><stop offset="1" stop-color="#6e7f98"/></linearGradient><radialGradient id="sphere-${safeId}" cx=".3" cy=".2" r=".8"><stop stop-color="#dfe6f2"/><stop offset=".5" stop-color="#7d8ca4"/><stop offset="1" stop-color="#1c273a"/></radialGradient></defs><circle cx="200" cy="110" r="96" stroke="white" stroke-opacity=".04" fill="none"/><circle cx="200" cy="110" r="120" stroke="white" stroke-opacity=".03" fill="none"/><path d="M0 110h400M200 0v220" stroke="white" stroke-opacity=".03" stroke-dasharray="2 7"/>${scene}</svg>`;
}
